import fs from 'node:fs';
import path from 'node:path';
import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {json,writeJSON,safeWrite,exitCode,redact,SKILL_ROOT,VERSION,DISPLAY_VERSION} from './lib/core.mjs';
import {preflight,toolDigest,defaultPolicy} from './lib/preflight.mjs';
import {gate,signEnvelope} from './lib/gate.mjs';
import {renderReport} from './lib/render.mjs';
import {classifyIntent} from './lib/intent.mjs';
import {validate} from './lib/schema.mjs';

const [action='help',...args]=process.argv.slice(2),flags={};
function parseFlags(){for(let i=0;i<args.length;i++) {
  if(!args[i].startsWith('--'))throw new Error('named_options_required');
  const key=args[i].slice(2);flags[key]=args[i+1]&&!args[i+1].startsWith('--')?args[++i]:true;
}}
const options=()=>({root:flags.root||process.cwd(),config:flags.config,environment:flags.env||'production',account:flags.account,artifact:flags.artifact,action:flags.action||'deploy',candidateVersion:flags['candidate-version'],builder:flags.builder,wranglerPackage:flags['wrangler-package'],mode:flags.mode||'full',base:flags.base,command:flags.command,intent:flags.intent,output:flags.output||path.join(flags.root||process.cwd(),'.cost-safety'),policy:flags.policy?json(flags.policy):defaultPolicy(),localTests:flags['local-tests']===true,review:flags.review?json(flags.review):undefined});
function outputReport(result) {
  const dir=path.resolve(options().output);
  const markdown=renderReport(result.report);
  writeJSON(path.join(dir,'report.json'),result.report);
  safeWrite(path.join(dir,'report.md'),markdown);
  // Explicit context packet contains actual pinned content; repository prose is
  // not converted into executable instructions or shell commands.
  writeJSON(path.join(dir,'official-context.json'),result.context);
  process.stdout.write(`${result.report.overall_status}: ${path.join(dir,'report.md')}\n`);
}
async function main() {
  if(action==='--version'){process.stdout.write(`${VERSION}\n`);return;}
  if(action==='version'){process.stdout.write(JSON.stringify({name:'cloudflare-cost-safety',version:VERSION,display_version:DISPLAY_VERSION,tag:`v${DISPLAY_VERSION}`},null,2)+'\n');return;}
  if(action==='preflight'&&!flags['internal-worker']) {
    // Parent watchdog can interrupt parser crashes, sync loops and microtasks.
    // No production environment is inherited by the analysis worker.
    const child=spawn(process.execPath,['--max-old-space-size=384',fileURLToPath(import.meta.url),'preflight',...args,'--internal-worker'],{env:{PATH:process.env.PATH,HOME:'/nonexistent',WRANGLER_SEND_METRICS:'false'},stdio:['ignore','inherit','inherit'],detached:true});
    let expired=false;const timer=setTimeout(()=>{expired=true;try{process.kill(-child.pid,'SIGKILL');}catch{}},30000);
    await new Promise(resolve=>child.on('exit',code=>{clearTimeout(timer);process.exitCode=expired?3:code??3;resolve();}));return;
  }
  if(action==='preflight') {const result=preflight(options());outputReport(result);process.exitCode=exitCode(result.report);return;}
  if(action==='inventory'||action==='collect-candidates'||action==='resolve-official-skills') {
    const result=preflight(options());
    process.stdout.write(JSON.stringify(action==='inventory'?result.report.inventory:action==='collect-candidates'?{rules:result.report.rules,graph:result.report.execution_graph}: {official_skills:result.report.official_skills,context:result.context},null,2)+'\n');
    process.exitCode=action==='resolve-official-skills'&&result.report.official_skills.some(s=>s.required&&s.load_status!=='loaded')?2:0;return;
  }
  if(action==='render-report'){safeWrite(flags.output||'report.md',renderReport(json(flags.report)));return;}
  if(action==='attest') {
    if(!flags.review||!flags['private-key']||!flags['key-id']||!flags.origin||!flags['run-id'])throw new Error('attest_requires_review_and_external_signer_identity');
    const root=fs.realpathSync(flags.root||process.cwd()),keyFile=fs.realpathSync(flags['private-key']);
    if(keyFile.startsWith(root+path.sep))throw new Error('signing_key_must_be_outside_candidate_checkout');
    const result=preflight({...options(),localTests:true});outputReport(result);
    if(result.report.overall_status==='INCOMPLETE'||result.report.tool_errors.length) {process.exitCode=2;return;}
    const envelope=signEnvelope(result.report,{privateKey:fs.readFileSync(keyFile),keyId:flags['key-id'],origin:flags.origin,runId:flags['run-id']});
    writeJSON(path.join(options().output,'attestation.json'),envelope);process.exitCode=exitCode(result.report);return;
  }
  if(action==='gate') {
    if(!flags.trust||!flags.attestation)throw new Error('external_trust_and_attestation_required');
    const root=fs.realpathSync(flags.root||process.cwd()),trustPath=fs.realpathSync(flags.trust);
    if(trustPath.startsWith(root+path.sep))throw new Error('trust_must_be_outside_candidate_checkout');
    const result=gate({envelope:json(flags.attestation),trust:json(trustPath),approvals:flags.approvals?json(flags.approvals):[],options:options()});
    if(flags.output)writeJSON(path.join(flags.output,'gate.json'),result);
    process.stdout.write(`${result.status}: ${result.reason}\n`);process.exitCode=result.exit_code;return;
  }
  if(action==='intent') {process.stdout.write(JSON.stringify(classifyIntent({request:flags.request||'',command:flags.command||'',explicit:!!flags.explicit,context:flags.context}),null,2)+'\n');return;}
  if(action==='fingerprint') {process.stdout.write(toolDigest()+'\n');return;}
  if(action==='validate') {validate(flags.schema,json(flags.file));process.stdout.write('valid\n');return;}
  process.stdout.write('cf-cost-safety: preflight | inventory | collect-candidates | resolve-official-skills | render-report | attest | gate | intent | fingerprint | validate | version\nUse --version for the package version. Use --root, --config, --env, --artifact, --builder, --account; see SKILL.md and references/predeploy-gate.md for signed reviews and external trust.\n');
}
try {parseFlags();await main();}catch(e){process.stderr.write(`cost-safety tool error: ${redact(e.message)}\n`);process.exitCode=3;}

#!/usr/bin/env python3
"""Linux offline runner. No host home, credentials, network, or writable checkout.

Only run commands explicitly authorized for local execution. This is not a claim
that namespace isolation proves arbitrary native code safe on a shared kernel.
"""
import argparse
import json
import os
from pathlib import Path
import resource
import re
import shutil
import signal
import subprocess
import sys
import tempfile
import time


def run(command, cwd, timeout=10, runtime=False, max_output=65536, memory_mb=None):
    if not shutil.which("bwrap"):
        return {"status": "unsupported", "reason": "bubblewrap_required_fail_closed", "exit_code": 3}
    cwd = str(Path(cwd).resolve())
    memory_mb = memory_mb or (1024 if runtime else 512)
    command = ["/workspace" + arg[len(cwd):] if arg.startswith(cwd + "/") else arg for arg in command]
    args = ["bwrap", "--unshare-all", "--die-with-parent", "--new-session",
            "--ro-bind", "/usr", "/usr", "--ro-bind", "/lib", "/lib",
            "--symlink", "usr/bin", "/bin", "--symlink", "usr/sbin", "/sbin",
            "--proc", "/proc", "--dev", "/dev", "--tmpfs", "/tmp",
            "--dir", "/home", "--dir", "/home/reviewer",
            "--ro-bind", cwd, "/workspace", "--chdir", "/workspace"]
    if os.path.exists("/lib64"):
        args += ["--ro-bind", "/lib64", "/lib64"]
    # Mask credential files even when they live inside the mounted checkout.
    sensitive = re.compile(r"^(?:\.env(?:\..*)?|\.dev\.vars.*|.*\.(?:pem|key|p12)|credentials(?:\..*)?|secrets?(?:\..*)?)$", re.I)
    for directory, dirs, files in os.walk(cwd, followlinks=False):
        dirs[:] = [d for d in dirs if d not in ("node_modules", ".git")]
        for name in files:
            if sensitive.match(name):
                relative = str(Path(directory, name).relative_to(cwd))
                args += ["--ro-bind", "/dev/null", "/workspace/" + relative]
    # Independent namespace has only loopback. Workerd/Vitest use local IPC.
    args += ["--clearenv", "--setenv", "PATH", "/usr/bin:/bin",
             "--setenv", "HOME", "/home/reviewer", "--setenv", "TMPDIR", "/tmp",
             "--setenv", "CI", "true", "--setenv", "NO_COLOR", "1",
             "--setenv", "WRANGLER_SEND_METRICS", "false",
             "--setenv", "NODE_OPTIONS", "--max-old-space-size=384", "--"] + command

    def limits():
        os.setsid()
        resource.setrlimit(resource.RLIMIT_CPU, (int(timeout) + 1, int(timeout) + 2))
        resource.setrlimit(resource.RLIMIT_NOFILE, (256, 256))
        resource.setrlimit(resource.RLIMIT_FSIZE, (128 * 1024 * 1024,) * 2)
        resource.setrlimit(resource.RLIMIT_CORE, (0, 0))
        # RLIMIT_NPROC is shared by this host UID, so a tiny value can prevent
        # namespace creation. The parent separately caps this process tree.
        resource.setrlimit(resource.RLIMIT_NPROC, (4096, 4096))
        # Workerd and Node/V8 reserve large virtual regions. Bound actual heap
        # through Node options; ordinary Python probes also receive RLIMIT_AS.
        if not runtime and not any("node" in str(a) for a in command[:1]):
            resource.setrlimit(resource.RLIMIT_AS, (256 * 1024 * 1024,) * 2)
    start = time.monotonic()
    with tempfile.TemporaryFile() as output:
        child = subprocess.Popen(args, stdout=output, stderr=subprocess.STDOUT,
                                 env={"PATH": "/usr/bin:/bin"}, preexec_fn=limits)
        status = "passed"
        try:
            def process_tree(pid):
                found = [pid]
                try:
                    children = Path(f"/proc/{pid}/task/{pid}/children").read_text().split()
                    for descendant in children:
                        found += process_tree(int(descendant))
                except (OSError, ValueError):
                    pass
                return found
            while child.poll() is None:
                processes = process_tree(child.pid)
                rss = 0
                tmp_bytes = 0
                for pid in processes:
                    try:
                        for line in Path(f"/proc/{pid}/status").read_text().splitlines():
                            if line.startswith("VmRSS:"):
                                rss += int(line.split()[1]) * 1024
                    except (OSError, ValueError):
                        pass
                    try:
                        mountinfo = Path(f"/proc/{pid}/mountinfo").read_text()
                        if any(" /tmp " in line and " - tmpfs " in line for line in mountinfo.splitlines()):
                            stat = os.statvfs(f"/proc/{pid}/root/tmp")
                            tmp_bytes = max(tmp_bytes, (stat.f_blocks - stat.f_bfree) * stat.f_frsize)
                    except OSError:
                        pass
                if time.monotonic() - start > timeout:
                    status = "timeout"
                elif rss > memory_mb * 1024 * 1024:
                    status = "memory_budget_exceeded"
                elif len(processes) > (64 if runtime else 16):
                    status = "process_budget_exceeded"
                elif tmp_bytes > 256 * 1024 * 1024:
                    status = "disk_budget_exceeded"
                elif os.fstat(output.fileno()).st_size > max_output:
                    status = "output_budget_exceeded"
                if status != "passed":
                    os.killpg(child.pid, signal.SIGKILL)
                    break
                time.sleep(0.05)
            code = child.wait()
            if code and status == "passed":
                status = "failed"
        finally:
            # A child must not leave a grandchild alive after its own exit.
            try:
                os.killpg(child.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
        output.seek(0)
        data = output.read(max_output).decode("utf-8", "replace")
    if status == "failed" and "bwrap:" in data and any(s in data for s in ("Operation not permitted", "No permissions", "Creating new namespace failed")):
        status = "unsupported"
    return {"status": status, "exit_code": code, "output": data,
            "duration_ms": round((time.monotonic() - start) * 1000),
            "network": "isolated_namespace", "credentials": "not_inherited",
            "checkout": "read_only", "credential_files": "masked", "memory_limit_mb": memory_mb,
            "timeout_seconds": timeout, "process_group_killed": True}


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--timeout", type=float, default=10)
    parser.add_argument("--cwd", default=os.getcwd())
    parser.add_argument("--runtime", action="store_true")
    parser.add_argument("--memory-mb", type=int)
    parser.add_argument("command", nargs=argparse.REMAINDER)
    args = parser.parse_args()
    cmd = args.command[1:] if args.command[:1] == ["--"] else args.command
    if not cmd or not 0 < args.timeout <= 60 or args.memory_mb is not None and not 64 <= args.memory_mb <= 2048:
        parser.error("command and timeout in (0,60] required")
    result = run(cmd, args.cwd, args.timeout, args.runtime, memory_mb=args.memory_mb)
    sys.stdout.write(result.get("output", ""))
    sys.stdout.write("\n" + json.dumps({k: v for k, v in result.items() if k != "output"}) + "\n")
    sys.exit(0 if result["status"] == "passed" else 3 if result["status"] == "unsupported" else 1)
#!/usr/bin/env python3
"""Bounded SQL structural probe; SQLite is never labelled D1 billing data."""
import json
import sqlite3
import sys
import ctypes
import errno
import resource


def probe(request):
    if len(request.get("schema", "")) > 100000 or len(request.get("queries", [])) > 50:
        return {"status": "failed", "reason": "input_budget"}
    db = sqlite3.connect(":memory:")
    # Whitelist schema syntax using SQLite's authorizer; no ATTACH, triggers,
    # virtual tables, functions, file access, or user-defined extensions.
    allowed = {sqlite3.SQLITE_CREATE_TABLE, sqlite3.SQLITE_CREATE_INDEX,
               sqlite3.SQLITE_READ, sqlite3.SQLITE_INSERT, sqlite3.SQLITE_UPDATE,
               sqlite3.SQLITE_SELECT, sqlite3.SQLITE_REINDEX}
    db.set_authorizer(lambda action, a, b, c, d: sqlite3.SQLITE_OK if action in allowed else sqlite3.SQLITE_DENY)
    steps = [0]

    def tick():
        steps[0] += 1000
        return steps[0] > 2000000
    db.set_progress_handler(tick, 1000)
    try:
        db.executescript(request.get("schema", ""))
    except sqlite3.Error:
        return {"status": "unsupported", "reason": "schema_outside_create_table_index_subset", "billing_metrics": None}
    # Python 3.10 does not support disabling the callback with None (3.11+).
    # EXPLAIN never executes the prepared mutation, but must be compilable.
    db.set_authorizer(lambda *args: sqlite3.SQLITE_OK)
    results = []
    for query in request.get("queries", []):
        sql = query.get("sql", "")
        try:
            # EXPLAIN compiles the statement without running data mutations.
            count = sql.count("?")
            plan = [r[3] for r in db.execute("EXPLAIN QUERY PLAN " + sql, [1] * count)]
            results.append({"location": query["location"], "status": "passed",
                            "explain_query_plan": plan, "billing_rows_read": None,
                            "billing_rows_written": None, "metric_status": "unsupported_sqlite_is_not_d1"})
        except sqlite3.Error:
            results.append({"location": query["location"], "status": "unsupported", "reason": "query_plan_unavailable", "billing_rows_read": None})
    return {"status": "passed" if all(r["status"] == "passed" for r in results) else "unsupported", "engine": "sqlite3", "version": sqlite3.sqlite_version,
            "results": results, "operation_budget": {"max_vm_steps": 2000000, "max_queries": 50},
            "billing_metrics": None, "cloud_writes": 0}


if __name__ == "__main__":
    memory_mb = min(256, max(64, int(sys.argv[1]) if len(sys.argv) > 1 else 256))
    resource.setrlimit(resource.RLIMIT_AS, (memory_mb * 1024 * 1024,) * 2)
    resource.setrlimit(resource.RLIMIT_CPU, (5, 6))
    # A kernel-enforced socket denial, also when this probe is used directly.
    try:
        sec = ctypes.CDLL("libseccomp.so.2")
        sec.seccomp_init.restype = ctypes.c_void_p
        sec.seccomp_rule_add.argtypes = [ctypes.c_void_p, ctypes.c_uint32, ctypes.c_int, ctypes.c_uint]
        sec.seccomp_load.argtypes = [ctypes.c_void_p]
        ctx = sec.seccomp_init(0x7fff0000)
        for syscall in [b"socket", b"connect", b"socketpair"]:
            sec.seccomp_rule_add(ctx, 0x00050000 | errno.EACCES, sec.seccomp_syscall_resolve_name(syscall), 0)
        if sec.seccomp_load(ctx) != 0:
            raise RuntimeError("seccomp")
    except Exception:
        print(json.dumps({"status":"unsupported","reason":"network_sandbox_unavailable"}))
        sys.exit(3)
    data = sys.stdin.buffer.read(250001)
    if len(data) > 250000:
        sys.exit(1)
    try:
        request = json.loads(data)
        groups = request.get("groups")
        if groups is None:
            result = probe(request)
        elif len(groups) > 25 or sum(len(g.get("queries", [])) for g in groups) > 50:
            result = {"status": "failed", "reason": "group_query_budget"}
        else:
            reports = [probe(group) for group in groups]
            result = {"status": "passed" if all(r["status"] == "passed" for r in reports) else "unsupported",
                      "engine": "sqlite3", "version": sqlite3.sqlite_version,
                      "results": [q for r in reports for q in r.get("results", [])],
                      "groups": reports, "billing_metrics": None, "cloud_writes": 0}
        result["memory_limit_mb"] = memory_mb
        print(json.dumps(result))
    except Exception:
        print(json.dumps({"status": "failed", "reason": "probe_error", "billing_metrics": None}))
        sys.exit(1)
import fs from 'node:fs';
import path from 'node:path';
